code.source:
#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {5, 2, 9, 1, 7};
    sort(v.begin(), v.end());
    for (int x : v) {
        cout << x << " ";
    }
    cout << endl;
    cout << *max_element(v.begin(), v.end()) << endl;
    reverse(v.begin(), v.end());
    cout << v[0] << endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {4, 8, 4, 1, 4};
    auto it = find(v.begin(), v.end(), 8);
    if (it != v.end()) {
        cout << "found at " << (it - v.begin()) << endl;
    }
    cout << count(v.begin(), v.end(), 4) << endl;
    cout << accumulate(v.begin(), v.end(), 0) << endl;
    return 0;
}

